import{_ as a,o as t,c as o,a8 as r}from"./chunks/framework.R_sesYpn.js";const p=JSON.parse('{"title":"API by example","description":"","frontmatter":{"title":"API by example"},"headers":[],"relativePath":"server/rest-api/by-example.md","filePath":"server/030_rest-api/003_by-example.md","lastUpdated":1786522245000}'),i={name:"server/rest-api/by-example.md"};function s(n,e,d,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="blacklab-server-api-by-example" tabindex="-1">BlackLab Server API by example <a class="header-anchor" href="#blacklab-server-api-by-example" aria-label="Permalink to &quot;BlackLab Server API by example&quot;">​</a></h1> <p>Let&#39;s look at some examples of how you use the API.</p> <p>This assumes you have a BlackLab Server instance running and have a corpus available. See <a href="/guide/getting-started.html">Getting started</a> if you don&#39;t have that yet.</p> <p><strong>NOTE:</strong> for readability, we won&#39;t URL-encode parameter values on this page.</p> <h2 id="api-4-vs-5" tabindex="-1">API 4 vs. 5 <a class="header-anchor" href="#api-4-vs-5" aria-label="Permalink to &quot;API 4 vs. 5&quot;">​</a></h2> <p>This page shows the newer API v5 URLs (that include <code>/corpora/</code>), which became available in BlackLab 4 and will be the default in BlackLab 5 (and current <code>dev</code> versions). If you get an error about the API version, try adding <code>api=5</code> to the URL.</p> <h2 id="json-vs-xml" tabindex="-1">JSON vs. XML <a class="header-anchor" href="#json-vs-xml" aria-label="Permalink to &quot;JSON vs. XML&quot;">​</a></h2> <p>Browsers show the XML response by default. Add <code>outputformat=json</code> to the URLs below to get the JSON response. (The <code>Accept</code> header also works, of course). For more details, see <a href="./api-info.html">here</a>.</p> <h2 id="information-about-the-server-and-corpora" tabindex="-1">Information about the server and corpora <a class="header-anchor" href="#information-about-the-server-and-corpora" aria-label="Permalink to &quot;Information about the server and corpora&quot;">​</a></h2> <p>The simplest request is the &quot;server info&quot; request: <code>/blacklab-server/</code>. The response will include:</p> <ul><li>BlackLab version information</li> <li>available corpora</li> <li>information about the <a href="/server/user-corpora.html">logged-in user</a>, if any</li> <li>available <a href="/development/customization/">plugins</a></li></ul> <p>You can get information about the <code>test</code> corpus: <code>/blacklab-server/corpora/test</code>. This includes:</p> <ul><li>time of creation/modification, BlackLab version used</li> <li>corpus size in documents and tokens</li> <li>annotated fields and metadata fields</li></ul> <p>If you add <code>listvalues=pos</code>, it will include all values for the <code>pos</code> annotation (up to a maximum of <code>limitvalues</code>, default 200). There&#39;s also <code>listmetadatavalues</code> for metadata fields. More information <a href="./information/corpus-info.html">here</a>.</p> <h2 id="find-matches" tabindex="-1">Find matches <a class="header-anchor" href="#find-matches" aria-label="Permalink to &quot;Find matches&quot;">​</a></h2> <p>Finding matches by searching for <a href="/guide/query-language/">BCQL query</a> patterns is done with the <code>/blacklab-server/corpora/test/hits</code> endpoint.</p> <p>Below will leave out the first part and just write <code>/hits?...</code></p> <p>To find all verbs and sort by document author, first 100 matches: <code>/hits?patt=[pos=&quot;VERB&quot;]&amp;sort=field:author&amp;first=0&amp;number=100</code>. The response will include:</p> <ul><li>the <code>hits</code> found</li> <li>information about the documents these hits occur in (<code>docInfos</code>)</li> <li>a <code>summary</code> of what was searched and how many results were found</li></ul> <p>Much more is possible with <code>/hits</code>; see <a href="./search/find-hits.html">here</a>.</p> <p>You can group these matches by various properties, such as the word before each hit: <code>/hits?patt=[pos=&quot;VERB&quot;]&amp;group=before:word:i:1</code>. See all sort and group criteria <a href="./search/find-hits.html#criteria-for-sorting-grouping-and-faceting">here</a>.</p> <details class="details custom-block"><summary>Running results count</summary> <p>When you&#39;re requesting a page of results (say the first 20), and there are more results to the query, BlackLab Server will keep processing these results in the background. When it returns the requested page of hits, it will also report how many it has processing so far and whether it has finished or is still processing/counting. This information is in the <code>summary.results.stats</code> section.</p> <p>If you need the total number of results right away, you can also pass <code>waitfortotal=true</code> and BlackLab will not respond until it has found all results.</p></details> <h2 id="find-documents" tabindex="-1">Find documents <a class="header-anchor" href="#find-documents" aria-label="Permalink to &quot;Find documents&quot;">​</a></h2> <p>Finding documents that match some filter can be done with the <code>/blacklab-server/corpora/test/docs</code> endpoint. We will again just write <code>/docs?...</code> below.</p> <p>To find documents with <em>guide</em> in the title, sorted by author and date, results 60-89: <code>/docs?filter=title:guide&amp;sort=field:author,field:date&amp;first=60&amp;number=30</code></p> <p>Documents matching a BCQL query, grouped by author: <code>/docs?patt=[lemma=&quot;bank&quot; &amp; pos=&quot;VERB&quot;]&amp;group=field:author</code></p> <p>More <a href="./search/find-documents.html">here</a>.</p> <h2 id="information-about-a-document" tabindex="-1">Information about a document <a class="header-anchor" href="#information-about-a-document" aria-label="Permalink to &quot;Information about a document&quot;">​</a></h2> <p>Each document has a PID (persistent identifier). (actually, it is only persistent if your <code>.blf.yaml</code> defines a <code>pidField</code>; see <a href="/guide/index-your-data/metadata.html#corpus-metadata">here</a>)</p> <p>This identifier can be used to retrieve information about the document. If we&#39;re interested in a document with PID 0345391802, here&#39;s what we can find:</p> <ul><li><code>/docs/0345391802</code>: document metadata</li> <li><code>/docs/0345391802/contents</code>: original (XML) document contents</li> <li><code>/docs/0345391802/contents?patt=[lemma=&quot;bank&quot; &amp; pos=&quot;VERB&quot;]</code>: document contents with matches highlighted (using <code>&lt;hl&gt;..&lt;/hl&gt;</code>)</li> <li><code>/docs/0345391802/contents?wordstart=1000&amp;wordend=2000</code>: part of the original document, so you can page through large documents</li> <li><code>/docs/0345391802/snippet?hitstart=120&amp;hitend=121&amp;context=50</code>: annotation values in a snippet of the document (similar to the <code>/hits</code> response, not the original document contents)</li></ul> <p>More information <a href="./documents/">here</a>.</p> <h2 id="this-concludes-our-tour" tabindex="-1">This concludes our tour <a class="header-anchor" href="#this-concludes-our-tour" aria-label="Permalink to &quot;This concludes our tour&quot;">​</a></h2> <p>Those are the most important endpoints in the BlackLab Server API.
Now you can dig into the various endpoints using the <a href="./index.html">reference</a>.</p>`,67)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
